package com.networkers.meetingautomation; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface MeetingGroupRepository extends JpaRepository<MeetingGroup,Long>{ boolean existsByChapterIdAndYearAndMonth(Long chapterId,int year,int month); List<MeetingGroup> findByChapterIdAndYearAndMonthOrderByGroupNumber(Long chapterId,int year,int month); List<MeetingGroup> findByCycleIdOrderByRoundNumberAscGroupNumberAsc(Long cycleId); List<MeetingGroup> findByCycleIdAndRoundNumberOrderByGroupNumberAsc(Long cycleId,int roundNumber); long countByCycleId(Long cycleId); @Query("select coalesce(max(g.groupNumber),0) from MeetingGroup g where g.chapter.id=:chapterId and g.year=:year and g.month=:month") int maxGroupNumber(@Param("chapterId") Long chapterId,@Param("year") int year,@Param("month") int month); @Modifying @Query("delete from MeetingGroup g where g.chapter.id=:chapterId and g.year=:year and g.month=:month") void deletePeriod(@Param("chapterId") Long chapterId,@Param("year") int year,@Param("month") int month); }
